window.OmniFeature=a=>{let observer=null,timer=null;const lists=new Set(),tracks=new Set(),cues=new Map(),attributes=new Map();function restoreCues(){for(const [cue,old]of cues){if(cue.line===old.applied&&cue.snapToLines===false){cue.line=old.line;cue.snapToLines=old.snap}}cues.clear()}function move(track){const position=a.settings.get('position');if(position==='original')return;let count=0;for(const cue of track.activeCues||[]){if(count++>=20||cues.size>=500)break;if(typeof cue.line==='undefined')continue;if(!cues.has(cue))cues.set(cue,{line:cue.line,snap:cue.snapToLines,applied:position==='raised'?65:85});cue.snapToLines=false;cue.line=cues.get(cue).applied}}function event(e){move(e.target)}function scan(){timer=null;if(!a.active)return;let count=0;for(const video of document.querySelectorAll('video')){if(count++>=20)break;if(!lists.has(video.textTracks)){lists.add(video.textTracks);video.textTracks.addEventListener('addtrack',schedule)}for(const track of video.textTracks){if(tracks.size>=100)break;if(!tracks.has(track)){tracks.add(track);track.addEventListener('cuechange',event)}move(track)}}}function schedule(){if(timer===null)timer=setTimeout(scan,250)}function attrs(){const root=document.documentElement;for(const [key,allowed]of [['size',['22','28','36','44']],['color',['white','yellow','black']],['background',['dark','clear','light']]]){const name='data-ob-caption-'+key,value=a.settings.get(key);if(!allowed.includes(value))continue;if(!attributes.has(name))attributes.set(name,{old:root.getAttribute(name),ours:value});attributes.get(name).ours=value;root.setAttribute(name,value)}}function stop(){observer?.disconnect();clearTimeout(timer);timer=null;document.removeEventListener('loadedmetadata',schedule,true);for(const track of tracks)track.removeEventListener('cuechange',event);tracks.clear();for(const list of lists)list.removeEventListener('addtrack',schedule);lists.clear();restoreCues();for(const[name,v]of attributes)if(document.documentElement.getAttribute(name)===v.ours){if(v.old===null)document.documentElement.removeAttribute(name);else document.documentElement.setAttribute(name,v.old)}attributes.clear()}return{enable(){attrs();scan();observer=new MutationObserver(schedule);observer.observe(document.documentElement,{childList:true,subtree:true});document.addEventListener('loadedmetadata',schedule,true)},update(){restoreCues();attrs();scan()},disable:stop}};